function coachQuickFeatures(){
  return[
    {key:'contract',label:'门店签约',icon:'contract'},
    {key:'work',label:'工作时间',icon:'clock'},
    {key:'course',label:'课程管理',icon:'course'},
    {key:'booking',label:'预约管理',icon:'booking'},
    {key:'calendar',label:'排课日历',icon:'schedule'},
    {key:'student',label:'学员管理',icon:'student'},
    {key:'order',label:'私教订单',icon:'order'}
  ];
}
