function renderCoachHomeLayout(){const page=$('homePage');if(page&&page.dataset.layoutReady!=='coach-v2'){page.innerHTML=coachHomeTemplate();page.dataset.layoutReady='coach-v2'}}
function getCoachStoreName(){const scheduleStore=schedules.find(item=>item.store&&item.status!=='已取消')?.store;const courseStore=courses.find(item=>item.stores)?.stores;return scheduleStore||courseStore||'黄毛健身房'}
function getCoachGreetingText(){const hour=new Date().getHours();if(hour<12)return'上午好';if(hour<18)return'下午好';return'晚上好'}
function getScheduleActiveMembers(schedule){return ensureScheduleMembers(schedule).filter(member=>member.status!=='已取消')}
function getCoachTodaySchedules(){const todayKey=fmtISO(today);return schedules.filter(schedule=>schedule.date===todayKey&&schedule.status!=='已取消'&&getScheduleActiveMembers(schedule).length>0).sort((a,b)=>timeToMin(a.start)-timeToMin(b.start))}
function getCoachMonthSchedules(){const monthKey=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}`;return schedules.filter(schedule=>String(schedule.date||'').startsWith(monthKey)&&schedule.status!=='已取消'&&getScheduleActiveMembers(schedule).length>0)}
function getCoachEarliestTime(list){return list.length?list[0].start:'--:--'}
function coachStatusView(schedule){const members=getScheduleActiveMembers(schedule);if(members.some(member=>member.status==='上课中'))return{text:'上课中',tone:'active'};if(members.some(member=>member.status==='待学员确认完课'))return{text:'待确认',tone:'review'};if(members.every(member=>['已完课','未到场'].includes(member.status)))return{text:'已完成',tone:'done'};if(members.some(member=>member.status==='待上课'))return{text:'待上课',tone:'pending'};return{text:'已预约',tone:'pending'}}
function coachCourseMetaText(schedule){const members=getScheduleActiveMembers(schedule);const names=members.map(member=>member.name).filter(Boolean);const memberText=schedule.courseType==='一对多'?`${names.slice(0,2).join('、')}${names.length>2?`等${names.length}人`:names.length?'':'多人课程'}`:(names[0]||'待分配学员');return `${memberText} · ${schedule.store||'未设置门店'}`}
function getCoachHomeStats(){const todaySchedules=getCoachTodaySchedules();const monthSchedules=getCoachMonthSchedules();return[{icon:'calendarCheck',label:'今日课程',value:todaySchedules.length,unit:'节',note:todaySchedules.length?`最早 ${getCoachEarliestTime(todaySchedules)} 开始`:'今日暂无课程'},{icon:'chart',label:'本月课程',value:monthSchedules.length,unit:'节',note:`本月已安排 ${monthSchedules.length} 节`},{icon:'users',label:'学员总数',value:getCoachStudentCount(),unit:'人',note:'按已预约学员去重统计'}]}
function getCoachTodoItems(){const items=[];getCoachTodaySchedules().forEach(schedule=>{getScheduleActiveMembers(schedule).forEach(member=>{if(member.status==='待上课'){items.push({scheduleId:schedule.id,bookingId:member.bookingId,time:schedule.start,courseName:schedule.courseName,memberName:member.name,statusText:'待上课',tone:'pending',action:'start',buttonText:'开始上课'})}else if(member.status==='上课中'&&member.source==='user'){items.push({scheduleId:schedule.id,bookingId:member.bookingId,time:schedule.start,courseName:schedule.courseName,memberName:member.name,statusText:'待完课',tone:'review',action:'finish',buttonText:'确认完课'})}})});return items.sort((a,b)=>timeToMin(a.time)-timeToMin(b.time))}
function renderCoachStatCards(){const box=$('coachStatGrid');if(!box)return;box.innerHTML=getCoachHomeStats().map(item=>`<div class="coach-stat-box"><div class="coach-stat-icon">${coachIcon(item.icon)}</div><div class="coach-stat-name">${item.label}</div><div class="coach-stat-number">${item.value}<small>${item.unit}</small></div><div class="coach-stat-note">${item.note}</div></div>`).join('')}
function renderCoachTodoList(){const box=$('coachTodoList');if(!box)return;const items=getCoachTodoItems();if(!items.length){box.innerHTML='<div class="coach-empty-state">今天暂时没有需要处理的课程，当前状态都已经同步好了。</div>';return}box.innerHTML=`<div class="coach-todo-list">${items.map(item=>`<div class="coach-todo-item"><div class="coach-todo-time">${item.time}</div><div class="coach-todo-main" onclick="openCoachScheduleDetail(${item.scheduleId})"><div class="coach-todo-top"><div class="coach-todo-name">${item.courseName}</div><span class="coach-chip ${item.tone}">${item.statusText}</span></div><div class="coach-todo-meta">${item.memberName} · ${fmtISO(today)} 星期${dayName(fmtISO(today))}</div></div><button class="coach-todo-btn" onclick="handleCoachTodoAction(${item.scheduleId},'${item.bookingId}','${item.action}')">${item.buttonText}</button></div>`).join('')}</div>`}
function renderCoachTodayCourseList(){const box=$('coachTodayCourseList');if(!box)return;const items=getCoachTodaySchedules();if(!items.length){box.innerHTML='<div class="coach-empty-state">今天还没有已预约的课程，新的预约会自动回填到这里。</div>';return}box.innerHTML=`<div class="coach-course-list">${items.map(schedule=>{const status=coachStatusView(schedule);return`<div class="coach-course-item" onclick="openCoachScheduleDetail(${schedule.id})"><div class="coach-course-row"><div><div class="coach-course-name">${schedule.courseName}</div><div class="coach-course-meta">${coachCourseMetaText(schedule)}<br/>${fmtMD(new Date(schedule.date+'T00:00:00'))} 星期${dayName(schedule.date)} ${schedule.start}-${schedule.end}</div></div><span class="coach-chip ${status.tone}">${status.text}</span></div></div>`}).join('')}</div>`}
function renderCoachHome(){renderCoachHomeLayout();if($('coachGreeting'))$('coachGreeting').innerText=`${getCoachGreetingText()}，${DEFAULT_COACH_NAME}`;if($('coachStoreName'))$('coachStoreName').innerText=getCoachStoreName();renderCoachStatCards();renderCoachTodoList();renderCoachTodayCourseList()}
function showCoachPage(id){document.querySelectorAll('.page').forEach(page=>page.classList.remove('active'));$(id).classList.add('active');saveActivePage(id);if(id==='homePage')renderCoachHome();if(id==='listPage')renderList();if(id==='workPage')renderWorkList();if(id==='calendarPage')renderCalendar();if(id==='userCoursePage')renderUserCourseList();if(id==='userBookingPage')renderUserBookingPage();if(id==='userSuccessPage')renderUserSuccessPage();if(id==='userBookingsPage')renderUserBookings()}
window.showPage=showPage=showCoachPage
window.openCoachFeature=function(feature){if(feature==='work'){showCoachPage('workPage');return}if(feature==='course'){showCoachPage('listPage');return}if(feature==='calendar'){showCoachPage('calendarPage');return}toast('该功能正在建设中')}
window.openCoachScheduleDetail=function(scheduleId){currentScheduleId=scheduleId;openDetail(scheduleId)}
window.handleCoachTodoAction=function(scheduleId,bookingId,action){currentScheduleId=scheduleId;if(action==='start'){updateBookingRecord(bookingId,{status:'上课中'});toast('已开始上课')}else{updateBookingRecord(bookingId,{status:'已完课',completedAt:new Date().toISOString()});toast('已确认完课')}renderCoachHome()}
function getCoachStatusTime(){const now=new Date();return `${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`}
