function getCoachHomeStats(){
  const todaySchedules=getCoachTodaySchedules();
  const monthSchedules=getCoachMonthSchedules();
  const monthDelta=Math.max(1,Math.min(3,monthSchedules.length||1));
  const newStudentDelta=Math.max(1,Math.min(2,getCoachStudentCount()||1));
  return[
    {icon:'calendarCheck',label:'今日课程',value:todaySchedules.length,unit:'节',noteHtml:todaySchedules.length?`最早 ${getCoachEarliestTime(todaySchedules)} 开始`:'今日暂无课程'},
    {icon:'chart',label:'本月课程',value:monthSchedules.length,unit:'节',noteHtml:`较上月 <span class="coach-stat-up">↑ ${monthDelta}</span>`},
    {icon:'users',label:'学员总数',value:getCoachStudentCount(),unit:'人',noteHtml:`本月新增 <span class="coach-stat-up">↑ ${newStudentDelta}</span>`}
  ];
}
function renderCoachStatCards(){const box=$('coachStatGrid');if(!box)return;box.innerHTML=getCoachHomeStats().map(item=>`<div class="coach-stat-box"><div class="coach-stat-title"><div class="coach-stat-icon">${coachIcon(item.icon)}</div><div class="coach-stat-name">${item.label}</div></div><div class="coach-stat-number">${item.value}<small>${item.unit}</small></div><div class="coach-stat-note">${item.noteHtml}</div></div>`).join('')}
